import jsonimport osFILE = "pnl_log.json"def load():    if not os.path.exists(FILE):        return []    return json.load(open(FILE))def save(data):    json.dump(data, open(FILE, "w"), indent=2)def record(symbol, pnl):    data = load()    data.append({        "symbol": symbol,        "pnl": pnl    })    save(data)def stats():    data = load()    if not data:        return {}    total = sum(x["pnl"] for x in data)    wins = len([x for x in data if x["pnl"] > 0])    losses = len([x for x in data if x["pnl"] <= 0])    return {        "total": total,        "wins": wins,        "losses": losses    }